export abstract class Store<T extends Item> extends EventEmitter implements Iterable<T> {
  #items = new Map<string, T>();
  protected static readonly VERSION = '1.0' as const;

  constructor(private readonly name: string, public limit = 1_000) { super(); }

  /** Add an item. */
  async add(item: T, at: Date = new Date()): Promise<boolean> {
    if (this.#items.has(item.id) || this.#items.size >= this.limit) return false;
    this.#items.set(item.id, { ...item, tags: [...item.tags, `at:${at.toISOString()}`] });
    return true;
  }

  abstract validate(item: T): item is T & { value: NonNullable<T['value']> };
  *[Symbol.iterator](): Iterator<T> { yield* this.#items.values(); }
}

